  namespace: string;
}

export type FormMode = "create" | "edit";
export type FormPresentation = "drawer" | "modal";
export type FormFieldType =
  | "checkbox"
  | "collection"
  | "custom"
  | "date"
  | "dynamic-value"
  | "dynamicValue"
  | "multiSelect"
  | "number"
  | "radio"
  | "select"
